{
  "name": "Arduino I/O控制模块",
  "name_en": "Arduino I/O Module",
  "manufacturer": "",
  "description": "基于Arduino的通用微控制器I/O模块，可提供数字输入/输出、模拟电压采集、PWM输出、脉冲输出以及舵机控制等功能。实验室中常用于连接简单传感器、读取开关或模拟信号、驱动指示灯与小型执行器，并实现基础自动化控制与原型验证。",
  "description_en": "A general-purpose Arduino-based microcontroller I/O module that provides digital input/output, analog voltage readback, PWM output, pulse generation, and servo control. In laboratories, it is commonly used to interface simple sensors, read switch or analog signals, drive indicators and small actuators, and support basic automation and prototyping.",
  "tag_hints": [
    "Arduino",
    "microcontroller I/O",
    "digital input output",
    "analog voltage measurement",
    "PWM output",
    "servo control",
    "sensor interfacing",
    "lab automation prototyping"
  ],
  "actions": [
    {
      "action_name": "auto-initialize",
      "description": "初始化Arduino I/O模块。",
      "description_en": "Initialize the Arduino I/O module."
    },
    {
      "action_name": "auto-reset",
      "description": "复位Arduino I/O模块。",
      "description_en": "Reset the Arduino I/O module."
    },
    {
      "action_name": "auto-conf_io",
      "description": "配置指定引脚为数字输入或数字输出。",
      "description_en": "Configure the selected pin as a digital input or digital output."
    },
    {
      "action_name": "auto-conf_servo",
      "description": "将指定通道配置为舵机控制输出。",
      "description_en": "Configure the selected channel for servo control output."
    },
    {
      "action_name": "auto-set_servo_us",
      "description": "设置舵机控制脉冲宽度（微秒）。",
      "description_en": "Set the servo control pulse width in microseconds."
    },
    {
      "action_name": "auto-get_analog_mv",
      "description": "读取指定模拟输入通道的电压，单位为毫伏。",
      "description_en": "Read the voltage of the selected analog input channel in millivolts."
    },
    {
      "action_name": "auto-get_analog_v",
      "description": "读取指定模拟输入通道的电压，单位为伏。",
      "description_en": "Read the voltage of the selected analog input channel in volts."
    },
    {
      "action_name": "auto-get_dig_in",
      "description": "读取指定数字输入引脚的逻辑电平状态。",
      "description_en": "Read the logic level state of the selected digital input pin."
    },
    {
      "action_name": "auto-set_dig",
      "description": "设置指定数字输出引脚的逻辑电平。",
      "description_en": "Set the logic level of the selected digital output pin."
    },
    {
      "action_name": "auto-set_pwm",
      "description": "设置指定通道的PWM输出值。",
      "description_en": "Set the PWM output value of the selected channel."
    },
    {
      "action_name": "auto-fade_pwm",
      "description": "在设定时间内将PWM输出从起始值渐变到结束值。",
      "description_en": "Ramp the PWM output from a start value to an end value over the specified time."
    },
    {
      "action_name": "auto-pulse_pin",
      "description": "在指定引脚上输出一次高电平或低电平脉冲。",
      "description_en": "Generate a high-level or low-level pulse on the selected pin."
    },
    {
      "action_name": "auto-set_led",
      "description": "设置板载LED的开关状态。",
      "description_en": "Set the on/off state of the onboard LED."
    }
  ]
}

